{
    public int Value;
    public void Increment() { Value++; }
}

class Program
{
    static void Main()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            var header = line.Split(' ');
            int n = int.Parse(header[0]);
            int rounds = int.Parse(header[1]);
            var initial = n > 0 ? Console.ReadLine().Split(' ') : Array.Empty<string>();

            var counters = new List<Counter>();
            for (int i = 0; i < n; i++)
            {
                counters.Add(new Counter { Value = int.Parse(initial[i]) });
            }

            for (int r = 0; r < rounds; r++)
