"""Random counter lists, incremented a random number of rounds -- a
solution that silently does nothing reports the original values back
unchanged no matter how many rounds run."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(1, 10)
    rounds = rng.randint(1, 5)
    initial = [rng.randint(-20, 20) for _ in range(n)]
    lines = ["%d %d" % (n, rounds), " ".join(map(str, initial))]
    return {"name": "%d counters, %d round(s) #%d" % (n, rounds, index),
            "stdin": "\n".join(lines) + "\n"}
